/* answer_states_result: does the prose state the runtime's number?
 *
 * The predicate behind the "[runtime result: ...]" correction. It must NOT fire on a correct
 * answer -- a false positive puts a correction on a right answer, which is worse than the 2-4%
 * it exists to catch. Both directions are asserted.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int answer_states_result(const char *ans, const char *res);
#define main tlm_unused_main
#include "ansmatch_impl.h"   /* generated by the Makefile FROM device_app.c -- never a copy */
#undef main

static int F = 0;
static void ck(const char *ans, const char *res, int want, const char *why) {
    int got = answer_states_result(ans, res);
    if (got != want) { F++; printf("  FAIL %-46s got=%d want=%d\n", why, got, want); }
}
int main(void) {
    /* states it -- must NOT be flagged */
    ck(" That gives 20000 Pa. Using p=F/A.", "20000", 1, "exact match");
    ck(" That gives 2e+04 Pa.",              "20000", 1, "same value, e-notation");
    ck(" The kinetic energy is 9 J.",        "9",     1, "single digit");
    ck(" K = 288000000 J.",                  "288000000", 1, "nine digits");
    ck(" 6079000 J from W=F*d.",             "6078669.911", 1, "4 s.f. rounding is not a mismatch");
    ck(" Using m = 900 and v = 800, K = 288000000 J.", "288000000", 1,
       "givens present too -- the RESULT is what matters");
    ck(" That gives -12.5 m/s.",             "-12.5", 1, "negative");
    /* does NOT state it -- must be flagged */
    ck(" K = 229 J. From K=0.5*m*(v)^(2).",  "288000000", 0, "THE DEVICE CASE: wrong digits");
    ck(" V = 250 V.",                        "8988000000", 0, "restated a GIVEN, not the result");
    ck(" That gives 3.833e+09 Hz.",          "383375.9591", 0, "wrong exponent");
    ck(" P = 51890 W.",                      "518940",     0, "one zero short");
    ck(" I cannot answer that.",             "20000",      0, "no number at all");
    printf("%s: answer_states_result, %d failure(s)\n", F ? "FAIL" : "PASS", F);
    return F ? 1 : 0;
}
